<script setup>
import {Head,useForm} from '@inertiajs/vue3'
import AppLayout from '../../Layouts/AppLayout.vue'
const p=defineProps({profile:Object,sessions:Array})
const labels={ADMIN:'مدیر',TEACHER:'مدرس',STUDENT:'هنرجو'}
const info=useForm({first_name:p.profile.first_name,last_name:p.profile.last_name,email:p.profile.email||'',bio:p.profile.bio||'',teacher_specialty:p.profile.teacher_specialty||'',teacher_experience_text:p.profile.teacher_experience_text||''})
const avatar=useForm({avatar:null})
const password=useForm({current_password:'',password:'',password_confirmation:''})
</script>
<template><AppLayout><Head title="پروفایل من"/><div class="space-y-5"><section class="rounded-2xl border bg-white p-5"><div class="flex items-center gap-4"><img v-if="profile.avatar_url" :src="profile.avatar_url" alt="" class="h-20 w-20 rounded-full object-cover"><div v-else class="grid h-20 w-20 place-items-center rounded-full bg-teal-50 text-2xl font-bold text-teal-800">{{profile.first_name?.[0]}}{{profile.last_name?.[0]}}</div><div><h1 class="text-2xl font-bold">{{profile.name}}</h1><p class="text-slate-500">{{labels[profile.role]}} · {{profile.is_active?'فعال':'غیرفعال'}}</p></div></div><form class="mt-4 flex flex-wrap items-center gap-3" @submit.prevent="avatar.post('/account/profile/avatar',{forceFormData:true})"><input type="file" accept="image/jpeg,image/png,image/webp" @change="avatar.avatar=$event.target.files[0]"><button class="rounded-xl border px-4 py-2">تغییر تصویر</button><p class="text-sm text-red-600">{{avatar.errors.avatar}}</p></form></section><section class="rounded-2xl border bg-white p-5"><h2 class="font-bold">اطلاعات حساب</h2><form class="mt-4 grid gap-4 sm:grid-cols-2" @submit.prevent="info.put('/account/profile')"><div><label>نام</label><input v-model="info.first_name"><p class="text-red-600">{{info.errors.first_name}}</p></div><div><label>نام خانوادگی</label><input v-model="info.last_name"><p class="text-red-600">{{info.errors.last_name}}</p></div><div><label>ایمیل</label><input v-model="info.email" type="email" dir="ltr"><p class="text-red-600">{{info.errors.email}}</p></div><div><label>موبایل (فقط توسط مدیر قابل تغییر)</label><input :value="profile.mobile" disabled dir="ltr"></div><div class="sm:col-span-2"><label>درباره من</label><textarea v-model="info.bio" rows="4" class="w-full rounded-xl border p-3"></textarea></div><template v-if="profile.role==='TEACHER'"><div><label>تخصص آموزشی</label><input v-model="info.teacher_specialty"></div><div class="sm:col-span-2"><label>تجربه حرفه‌ای</label><textarea v-model="info.teacher_experience_text" rows="4" class="w-full rounded-xl border p-3"></textarea></div></template><button class="w-fit rounded-xl bg-teal-700 px-5 py-2 text-white">ذخیره پروفایل</button></form></section><section class="rounded-2xl border bg-white p-5"><h2 class="font-bold">امنیت</h2><form class="mt-4 grid gap-3 sm:grid-cols-3" @submit.prevent="password.put('/account/profile/password',{onSuccess:()=>password.reset()})"><input v-model="password.current_password" type="password" placeholder="رمز فعلی"><input v-model="password.password" type="password" placeholder="رمز جدید"><input v-model="password.password_confirmation" type="password" placeholder="تکرار رمز جدید"><p class="text-sm text-red-600 sm:col-span-3">{{password.errors.current_password||password.errors.password}}</p><button class="w-fit rounded-xl border px-5 py-2">تغییر رمز</button></form></section><section class="rounded-2xl border bg-white p-5"><h2 class="font-bold">نشست‌های فعال</h2><div v-for="s in sessions" :key="s.token" class="mt-3 rounded-xl bg-slate-50 p-3 text-sm">{{s.device}} · {{s.ip}} · {{new Date(s.last_activity).toLocaleString('fa-IR')}} <span v-if="s.current">(نشست فعلی)</span></div></section></div></AppLayout></template>
